import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(0)
        return
    n = int(data[0])
    if n == 0:
        print(0)
        return
    total = 0
    for i in range(1, n + 1):
        if i < len(data):
            total += int(data[i])
    print(total)

if __name__ == "__main__":
    main()
